const lessons=[
{id:'be',level:'A1',title:'O verbo to be',subtitle:'Ser, estar e as primeiras apresentações',why:'Você usa am, is e are para dizer quem é, como está e de onde vem.',rule:'O verbo muda conforme o sujeito. Na negativa, acrescente not; na pergunta, inverta a ordem.',form:['Sujeito','am / is / are','complemento'],example:'She is from Brazil.',translation:'Ela é do Brasil.',wrong:'She are happy.',right:'She is happy.',tip:'I am · he/she/it is · you/we/they are.',qs:[['She ___ a teacher.',['am','is','are'],'is','Com she, usamos is.'],['___ you ready?',['Am','Is','Are'],'Are','Perguntas com you usam Are.']]},
{id:'present',level:'A1',title:'Present Simple',subtitle:'Rotinas, fatos e hábitos',why:'É o tempo para dizer o que você faz normalmente, não necessariamente agora.',rule:'Com he/she/it, acrescente -s ou -es ao verbo. Para negar/perguntar, use do ou does.',form:['Sujeito','verbo (s/es)','complemento'],example:'I work every day.',translation:'Eu trabalho todos os dias.',wrong:'She work on Mondays.',right:'She works on Mondays.',tip:'always, usually, often, every day → pistas de hábito.',qs:[['She ___ coffee every morning.',['drink','drinks','drinking'],'drinks','Com she, o verbo recebe -s.'],['___ they live in London?',['Do','Does','Are'],'Do','Usamos do com they para perguntar no presente simples.']]},
{id:'questions',level:'A1',title:'Construindo perguntas',subtitle:'Who, what, where, when, why e how',why:'Perguntar é o primeiro passo para sustentar uma conversa.',rule:'Nas perguntas com verbo comum, use palavra interrogativa + do/does + sujeito + verbo-base.',form:['Where / What / Why','do / does','sujeito + verbo?'],example:'Where do you live?',translation:'Onde você mora?',wrong:'Where you live?',right:'Where do you live?',tip:'Who = quem · what = o quê · where = onde · when = quando · why = por quê · how = como.',qs:[['___ do you work? At a hospital.',['Where','Who','When'],'Where','At a hospital responde a uma pergunta sobre lugar.'],['What ___ she do?',['do','does','is'],'does','Para perguntar sobre she no presente simples, usamos does.']]},
{id:'articles',level:'A1',title:'Artigos e substantivos',subtitle:'A, an, the e plurais',why:'Pequenos artigos ajudam a deixar sua fala natural.',rule:'A e an indicam algo não específico; the indica algo conhecido. A/an dependem do som inicial, não só da letra.',form:['a / an / the','substantivo','contexto'],example:'I have an idea.',translation:'Eu tenho uma ideia.',wrong:'She is a engineer.',right:'She is an engineer.',tip:'an hour (som de vogal) · a university (som de /y/).',qs:[['I need ___ umbrella.',['a','an','the'],'an','Umbrella começa com som de vogal.'],['She bought ___ book. The book is blue.',['a','an','—'],'a','Na primeira menção, usamos a book.']]},
{id:'continuous',level:'A1',title:'Present Continuous',subtitle:'O que está acontecendo agora',why:'Permite narrar o momento e falar de situações temporárias.',rule:'Use am/is/are + verbo com -ing. Não omita o auxiliar.',form:['Sujeito','am / is / are','verbo + ing'],example:'I am studying English now.',translation:'Estou estudando inglês agora.',wrong:'I studying English.',right:'I am studying English.',tip:'now, at the moment, right now → pistas de uma ação em andamento.',qs:[['They ___ dinner right now.',['cook','are cooking','cooks'],'are cooking','They pede are + verbo com -ing.'],['I ___ to music at the moment.',['listen','am listening','listens'],'am listening','At the moment aponta para present continuous.']]},
{id:'past',level:'A2',title:'Past Simple',subtitle:'Histórias e acontecimentos concluídos',why:'Você precisa do passado para falar de ontem, viagens e experiências específicas.',rule:'Use -ed em muitos verbos regulares; verbos irregulares mudam de forma. Negativa/pergunta: did + verbo-base.',form:['Sujeito','verbo no passado','complemento'],example:'We visited our friends yesterday.',translation:'Visitamos nossos amigos ontem.',wrong:'Did you went there?',right:'Did you go there?',tip:'yesterday, last week, in 2020 → passado concluído.',qs:[['I ___ a movie yesterday.',['see','saw','seen'],'saw','See tem passado irregular: saw.'],['Did she ___ you?',['called','call','calls'],'call','Depois de did, use o verbo na forma-base.']]},
{id:'prepositions',level:'A2',title:'Preposições',subtitle:'In, on, at e localização',why:'Você precisa delas para marcar onde e quando algo acontece.',rule:'Para tempo: at + hora; on + dia/data; in + mês/ano/período. Em lugares, o uso depende do contexto.',form:['at / on / in','tempo ou lugar','contexto'],example:'The meeting is on Monday.',translation:'A reunião é na segunda-feira.',wrong:'I wake up on 7 a.m.',right:'I wake up at 7 a.m.',tip:'at 8:00 · on Friday · in November.',qs:[['My birthday is ___ May.',['at','on','in'],'in','Para meses, use in.'],['I study English ___ night.',['at','on','in'],'at','At night é uma expressão de uso comum.']]},
{id:'future',level:'A2',title:'Futuro: will e going to',subtitle:'Decisões, promessas e planos',why:'Diferencie o que você decidiu agora do que já estava planejado.',rule:'Will costuma expressar decisão espontânea ou previsão; going to costuma expressar plano ou intenção prévia.',form:['Sujeito','will / be going to','verbo-base'],example:'I am going to travel next month.',translation:'Vou viajar no mês que vem.',wrong:'She will to study.',right:'She will study.',tip:'Will e going to também podem se sobrepor; o contexto importa.',qs:[['Look at those clouds! It ___ rain.',['is going to','was','does'],'is going to','A previsão se baseia numa evidência visível.'],['I think I ___ call her now.',['am','will','did'],'will','Will funciona para decisões tomadas no momento.']]},
{id:'modals',level:'A2',title:'Verbos modais',subtitle:'Can, could, should e must',why:'Permitem pedir ajuda, dar conselhos e falar de obrigação.',rule:'Depois de um modal, use o verbo-base sem to, inclusive com he/she/it.',form:['Sujeito','can / should / must','verbo-base'],example:'Could you help me, please?',translation:'Você poderia me ajudar, por favor?',wrong:'She can speaks English.',right:'She can speak English.',tip:'Can = capacidade · could = pedido educado · should = conselho · must = obrigação forte.',qs:[['You ___ drink more water. (conselho)',['should','can to','are'],'should','Should indica conselho.'],['He can ___ very well.',['swims','swim','swimming'],'swim','Depois de can, usamos a forma-base.']]},
{id:'perfect',level:'B1',title:'Present Perfect',subtitle:'Experiências e conexão com o presente',why:'É útil para dizer o que você já fez sem situar um passado exato.',rule:'Use have/has + particípio. Com tempo passado específico e encerrado, geralmente use past simple.',form:['Sujeito','have / has','particípio'],example:'I have visited London twice.',translation:'Eu já visitei Londres duas vezes.',wrong:'I have seen her yesterday.',right:'I saw her yesterday.',tip:'ever, never, already, yet, since, for são pistas comuns.',qs:[['She ___ never tried sushi.',['have','has','did'],'has','She usa has + particípio.'],['I ___ my keys yesterday.',['have lost','lost','lose'],'lost','Yesterday indica momento específico no passado.']]},
{id:'connectors',level:'B1',title:'Conectando ideias',subtitle:'Because, although, but e so',why:'Você deixa de falar frases isoladas e começa a explicar opiniões.',rule:'Because introduz motivo, so introduz consequência, although introduz contraste, but une ideias opostas.',form:['ideia','conector','nova ideia'],example:'I stayed home because it was raining.',translation:'Fiquei em casa porque estava chovendo.',wrong:'I was tired because I went to bed early. (para indicar consequência)',right:'I was tired, so I went to bed early.',tip:'Because = motivo · so = resultado · although = apesar de.',qs:[['It was late, ___ we went home.',['because','so','although'],'so','So introduz a consequência.'],['___ it was cold, we went outside.',['Although','Because','So'],'Although','Although expressa contraste.']]},
{id:'conditional',level:'B1',title:'Primeiro condicional',subtitle:'Situações futuras possíveis',why:'Você consegue falar de planos, hipóteses e consequências realistas.',rule:'Use if + present simple, will + verbo-base para consequências possíveis no futuro.',form:['If + present simple','will','verbo-base'],example:'If it rains, I will stay home.',translation:'Se chover, vou ficar em casa.',wrong:'If it will rain, I will stay.',right:'If it rains, I will stay.',tip:'A ordem pode mudar: I will stay home if it rains.',qs:[['If she studies, she ___ pass.',['will','would','is'],'will','No primeiro condicional, a consequência pode usar will.'],['If I ___ time, I will call you.',['will have','have','had'],'have','Depois de if, use present simple nessa construção.']]}
];
