const storageKey='verbarium:progress:v1';
const defaultData=()=>({completed:[],completedAt:{},lessonSessions:{},attempts:0,correct:0,activity:[],reviews:{},sessions:[],nickname:'Explorador'});
function loadData(){try{const saved=JSON.parse(localStorage.getItem(storageKey));return saved&&Array.isArray(saved.completed)&&saved.reviews?{...defaultData(),...saved}:defaultData()}catch{return defaultData()}}
const data=loadData();
const app={route:'home',chapter:'first',lesson:lessons[0].id,lessonIdx:0,lessonAnswer:null,lessonScore:0,filter:'Todos',labTab:'tenses',tense:'present',verbQuery:'',practiceMode:'mixed',round:[],roundIdx:0,roundAnswer:null,roundCorrect:0,reviewOnly:false,scenario:'cafe',step:0,dialog:[],dialogAnswer:null,micStatus:''};
const safe=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(a,b)=>b?Math.round(a/b*100):0;
const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function save(){try{localStorage.setItem(storageKey,JSON.stringify(data))}catch{}}
function announce(t){document.querySelector('#announcer').textContent=t}
function nextLesson(){return lessons.find(x=>!data.completed.includes(x.id))||lessons[0]}
const allQuestions=()=>[...lessons.flatMap(l=>l.qs.map((q,i)=>({id:`${l.id}-${i}`,type:'choice',prompt:q[0],options:q[1],correct:q[2],explain:q[3],topic:l.id}))),...writing.map(w=>({...w,type:'write'}))];
function findQ(id){return allQuestions().find(q=>q.id===id)}
function reviewItems(){return Object.entries(data.reviews).filter(([id])=>findQ(id)).sort((a,b)=>a[1].due-b[1].due)}
function dueItems(){return reviewItems().filter(([id,v])=>v.due<=Date.now())}
let pendingMissionCelebration=false;
function recordAttempt(ok,id){data.attempts++;if(ok)data.correct++;data.activity.push({date:day(),id,ok});if(data.activity.filter(e=>e.date===day()).length===3)pendingMissionCelebration=true;if(data.activity.length>1200)data.activity=data.activity.slice(-1200);const prev=data.reviews[id];if(!ok){data.reviews[id]={level:0,due:Date.now(),last:Date.now()}}else if(prev){const level=Math.min(4,(prev.level||0)+1);const periods=[0,1,3,7,14];data.reviews[id]={level,due:Date.now()+periods[level]*86400000,last:Date.now()}}save()}
function currentStreak(){const dates=new Set([...data.activity.map(e=>e.date),...(data.sessions||[]).map(e=>e.date)]);let cursor=new Date(),count=0;const localKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(!dates.has(localKey(cursor)))cursor.setDate(cursor.getDate()-1);for(let i=0;i<365;i++){if(!dates.has(localKey(cursor)))break;count++;cursor.setDate(cursor.getDate()-1)}return count}
function navHtml(mobile=false){const items=mobile?navItems.filter(a=>['home','learn','practice','speak','profile'].includes(a[0])):navItems;return items.map(([id,label,ic])=>`<button type="button" class="${mobile?'mobile-item':'nav-btn'} ${app.route===id?'active':''}" data-route="${id}" ${app.route===id?'aria-current="page"':''} aria-label="${label}"><span class="nav-icon">${navArtwork(id,app.route===id)||svg(ic)}</span><span class="${mobile?'mobile-text':'nav-text'}">${label.replace('Trilha de aulas','Aulas').replace('Revisar erros','Revisão').replace('Laboratório verbal','Verbos').replace('Meu progresso','Progresso').replace('Meu perfil','Perfil')}</span></button>`).join('')}
function renderChrome(){document.querySelector('#desktop-nav').innerHTML=navHtml();document.querySelector('#mobile-nav').innerHTML=navHtml(true);document.querySelector('#breadcrumb').textContent=({'home':'Início','learn':'Trilha de aulas','lesson':'Lição','lab':'Laboratório verbal','practice':'Praticar','speak':'Conversar','progress':'Meu progresso','profile':'Meu perfil','assets':'Biblioteca de assets','chapter':'Capítulo','review':'Revisão','motions':'Motion Library','v3':'Biblioteca de assets v3'})[app.route];document.querySelector('#top-completed').textContent=`${data.completed.length} / ${lessons.length} aulas`;document.querySelector('#top-progress').style.width=pct(data.completed.length,lessons.length)+'%'}
function renderRail(){let html='';if(app.route==='assets'||app.route==='v3')html=`<div class="rail-label">SISTEMA VISUAL</div><div class="rail-note"><h3>Kit v3: 151 sprites e 142 animações reais.</h3><p>PNG com canal alpha, SVGs escaláveis e componentes com valores reais. Confira contraste, resolução e composição na biblioteca.</p></div>`;
 else if(app.route==='home'||app.route==='learn'||app.route==='chapter')html=`<div class="rail-label">NOTA DE ESTUDO / 01</div><div class="rail-note"><div class="overline">APRENDA EM CAMADAS</div><h3>Entenda.<br>Use.<br>Repita.</h3><p>Uma regra faz mais sentido quando você a aplica numa pergunta, numa resposta e numa conversa.</p><div class="small-line"></div><p class="side-emphasis">I work. <span style="color:#90a78d">→</span><br>I am working.</p><p>Uma palavra muda o tempo. O contexto muda a mensagem.</p></div><div class="rail-card"><div class="overline">O DESAFIO DE HOJE</div><p>Faça uma pergunta em inglês sobre a rotina de alguém.</p><small>Experimente: <b>Where do you work?</b></small><br><button class="side-link" data-route="practice">Ir para os exercícios ${svg('arrow')}</button></div>`;
else if(app.route==='lesson')html=`<div class="rail-label">SEU CADERNO / AULA</div><div class="rail-note"><h3>Faça a frase trabalhar.</h3><p>Leia o exemplo, troque o sujeito e fale em voz alta. Saber reconhecer é diferente de conseguir produzir.</p><div class="small-line"></div><div class="overline">COMO PRATICAR</div><p>01 · Observe o exemplo.<br>02 · Diga uma frase sua.<br>03 · Teste o que aprendeu.<br>04 · Retome os erros.</p></div><div class="rail-card"><div class="overline">LEMBRETE</div><p>Errar cria sua próxima revisão.</p><small>As revisões ficam guardadas somente neste navegador.</small></div>`;
else if(app.route==='lab')html=`<div class="rail-label">ANOTAÇÃO / GRAMÁTICA</div><div class="rail-note"><h3>Tempo não é tradução literal.</h3><p>Compare <i>I work</i> (rotina) e <i>I am working</i> (em andamento). O tempo verbal descreve como a ação se situa no tempo.</p><div class="rail-timeline"><span></span><i></i><span></span></div><p>Escolha uma forma à esquerda para comparar estrutura, uso e exemplos.</p></div><div class="rail-card"><div class="overline">TREINE NA PRÁTICA</div><p>Uma regra só fixa quando vira resposta.</p><button class="side-link" data-route="practice">Exercícios ${svg('arrow')}</button></div>`;
else if(app.route==='practice'||app.route==='review'||app.route==='progress'||app.route==='profile')html=`<div class="rail-label">NOTA DE PRÁTICA</div><div class="rail-note"><h3>Recuperar é aprender.</h3><p>Antes de ver a resposta, tente lembrar sem olhar a explicação. Cada erro pode voltar para revisão.</p><div class="small-line"></div><div class="overline">SEU HISTÓRICO</div><p><strong>${data.attempts}</strong> respostas dadas<br><strong>${data.correct}</strong> respostas corretas<br><strong>${dueItems().length}</strong> revisões disponíveis</p></div><div class="rail-card"><div class="overline">DICA</div><p>Explique em voz alta por que escolheu a resposta.</p><small>O objetivo é compreender a frase, não colecionar acertos.</small></div>`;
else html=`<div class="rail-label">NOTA DE CONVERSAÇÃO</div><div class="rail-note"><h3>Leia. Ouça. Responda.</h3><p>Observe como frases curtas ganham função numa conversa real. Depois, use o botão de áudio e repita.</p><div class="small-line"></div><p><b>Importante:</b> este é um diálogo guiado com respostas pré-definidas, não um tutor de IA ao vivo.</p></div><div class="rail-card"><div class="overline">PRONÚNCIA</div><p>Fale sem correr. Clareza vem antes de velocidade.</p><small>O microfone usa a transcrição disponível no navegador, quando compatível.</small></div>`;
 document.querySelector('#rail').innerHTML=html}
