let previousRoute=null;
function paint(){
 renderChrome();
 const main=document.querySelector('#main');
 document.body.dataset.route=app.route;
  main.innerHTML=({home:homePage,learn:learnPage,chapter:chapterPage,lesson:lessonPage,lab:labPage,practice:practicePage,speak:speakPage,progress:progressPage,profile:profilePage,review:reviewPage,assets:assetGalleryPage,motions:renderMotionGallery,v3:renderV3Gallery})[app.route]();
 renderRail();
 hydrateIcons();
 hydrateVerbariumUI(main);
 hydrateAssetGallery(main);
 hydrateVerbariumMotion(main,app.route);
  hydrateV3(main,app.route);
  hydrateLessonKit(main);
  hydratePhaseMotion(main,app.route);
 if(pendingMissionCelebration){pendingMissionCelebration=false;queueMicrotask(()=>celebrateV3({kind:'mission'}))}
 if(previousRoute!==app.route){animateEntrance(main);previousRoute=app.route}
 else animateFeedback(main);
}
function goto(route){app.route=route;paint();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main').focus({preventScroll:true})}
