function homePage(){
 const next=nextLesson(), n=lessons.findIndex(l=>l.id===next.id)+1;
 const today=data.activity.filter(x=>x.date===day()).length;
 const completion=pct(data.completed.length,lessons.length);
 const streak=currentStreak();
 const week=weekActivity();
 return `<section class="hello-section"><div><div class="eyebrow"><span class="eyebrow-star">✦</span> SEU CANTINHO DE INGLÊS</div><h1 class="heading">Aprenda inglês de um jeito <em>seu.</em></h1><p class="lede">Uma aula por vez, mais confiança para a próxima conversa.</p></div><div class="hello-sticker" aria-hidden="true">✳<span>Let's go!</span></div></section>
 <section class="hero-card" aria-label="Continuar aprendendo"><div class="hero-content"><span class="hero-kicker"><span class="pulse-point"></span> CONTINUE DE ONDE PAROU</span><h2>${data.completed.length===lessons.length?'Todas as aulas concluídas! <em>Continue evoluindo.</em>':`Sua próxima aventura:<br><em>${safe(next.title)}</em>`}</h2><p>${safe(next.why)}</p><div class="hero-meter"><div class="hero-meter-top"><span>Sua trilha de aprendizado</span><strong>${completion}%</strong></div><div class="hero-progress"><i style="width:${completion}%"></i></div></div><div class="hero-actions"><button class="button bright vb-sprite-cta" data-action="open-lesson" data-id="${next.id}">${data.completed.length===lessons.length?'Revisitar aulas':'Continuar aprendendo'} ${svg('arrow')}</button><span class="hero-foot">${next.level} · cerca de 6 min</span></div></div><div class="hero-visual" aria-hidden="true">${renderHeroMascot()}</div></section>
 ${renderMissionBoard(missionState({activity:data.activity,completedAt:data.completedAt,sessions:data.sessions,today:day()}))}
 <div class="vb-home-streak">${renderStreakWeek(week,streak)}</div>
  <div class="section-head colorful"><h2 class="section-title">Meu plano de estudos <span>✿</span></h2><button class="text-button" data-route="progress">Meu progresso ${svg('arrow')}</button></div>
 
 <div class="v2-section-bar"><h2>Seu próximo mundo</h2><button class="text-button" data-route="learn">Ver toda a jornada →</button></div>
 ${renderQuestMap({lessons,completed:data.completed,currentId:next.id,lessonSessions:data.lessonSessions,compact:true})}
 <div class="section-head colorful"><h2 class="section-title">Explore e pratique <span>✦</span></h2><span class="minor">Escolha sua atividade</span></div><div class="quick-filters" aria-label="Acessos rápidos"><button class="quick-filter vb-quick-asset" data-route="learn"><img src="/verbarium-v3/assets/navigation/book_default.png" alt="" aria-hidden="true">Aulas</button><button class="quick-filter vb-quick-asset" data-route="lab"><img src="/verbarium-v3/assets/navigation/sprout_default.png" alt="" aria-hidden="true">Verbos & tempos</button><button class="quick-filter vb-quick-asset" data-route="practice"><img src="/verbarium-v3/assets/navigation/gamepad_default.png" alt="" aria-hidden="true">Exercícios</button><button class="quick-filter vb-quick-asset" data-route="speak"><img src="/verbarium-v3/assets/navigation/headphones_default.png" alt="" aria-hidden="true">Conversação</button></div>
 <div class="module-grid playful-grid"><button class="module-card featured" data-route="lab"><span class="module-top"><span class="module-glyph module-glyph-3d" aria-hidden="true"><img src="/verbarium-assets/icons/icon_layers_tile.png" alt="" width="96" height="96" loading="lazy" decoding="async"></span><span class="module-counter">7 tempos</span></span><h3>Laboratório<br>verbal</h3><p>Entenda quando usar cada tempo e descubra a lógica dos verbos.</p><span class="module-bottom"><span>Explore as formas</span><span class="arrow">${svg('arrow')}</span></span></button><button class="module-card warm" data-route="speak"><span class="module-top"><span class="module-glyph module-glyph-3d" aria-hidden="true"><img src="/verbarium-assets/icons/icon_play_tile.png" alt="" width="96" height="96" loading="lazy" decoding="async"></span><span class="module-counter">4 cenários</span></span><h3>Conversação<br>do dia a dia</h3><p>Treine no café, em viagens, no trabalho e em apresentações.</p><span class="module-bottom"><span>Vamos conversar</span><span class="arrow">${svg('arrow')}</span></span></button><button class="module-card blue" data-route="practice"><span class="module-top"><span class="module-glyph module-glyph-3d" aria-hidden="true"><img src="/verbarium-assets/icons/icon_clipboard_tile.png" alt="" width="96" height="96" loading="lazy" decoding="async"></span><span class="module-counter">Prática</span></span><h3>Hora de<br>praticar</h3><p>Construa frases e receba explicações para cada resposta.</p><span class="module-bottom"><span>Testar o inglês</span><span class="arrow">${svg('arrow')}</span></span></button><button class="module-card mint" data-route="learn"><span class="module-top"><span class="module-glyph module-glyph-3d" aria-hidden="true"><img src="/verbarium-assets/icons/icon_book_tile.png" alt="" width="96" height="96" loading="lazy" decoding="async"></span><span class="module-counter">A1 a B1</span></span><h3>Minha trilha<br>de aulas</h3><p>Aprenda do básico às estruturas para conversar melhor.</p><span class="module-bottom"><span>Ver todas as aulas</span><span class="arrow">${svg('arrow')}</span></span></button></div>
 <section class="weekly-card"><div class="weekly-intro"><div class="weekly-icon vb-weekly-medal"><img src="/verbarium-v3/assets/rewards/achievement_medal.png" alt="" aria-hidden="true" loading="lazy"></div><div><span class="overline">META DA SEMANA</span><h3>Um pouco por dia faz diferença.</h3><p>Responda algumas questões e mantenha sua prática ativa.</p></div></div><div class="week-days">${week.map(w=>`<span class="weekday ${w.active?'did':''}" title="${w.date}"><strong>${w.label}</strong><i>${w.active?'✓':'·'}</i></span>`).join('')}</div><button class="weekly-link" data-route="review" aria-label="Abrir revisão de erros">${svg('arrow')}</button></section>
 <p class="tool-tip" style="margin:18px 0">Trilha pedagógica inspirada no CEFR. O progresso é pessoal e salvo apenas neste navegador.</p>`
}
function weekActivity(){const todayDate=new Date(),active=new Set([...data.activity.map(a=>a.date),...(data.sessions||[]).map(s=>s.date)]);return Array.from({length:7},(_,i)=>{const d=new Date(todayDate);d.setDate(todayDate.getDate()-6+i);const date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {date,label:['D','S','T','Q','Q','S','S'][d.getDay()],active:active.has(date)}})}
function learnPage(){const filtered=lessons.filter(x=>app.filter==='Todos'||x.level===app.filter);return `<div class="page-intro"><div class="overline">APRENDIZADO ESTRUTURADO</div><h1 class="heading">Aprender é uma <em>jornada.</em></h1><p class="lede">Do primeiro “I am” às ideias conectadas. Cada aula traz uma explicação em português, um exemplo real e uma verificação do que você compreendeu.</p></div><div class="v2-section-bar"><h2>Três capítulos, uma jornada</h2><span>Sem bloqueios artificiais</span></div>
 ${renderQuestMap({lessons,completed:data.completed,currentId:nextLesson().id,lessonSessions:data.lessonSessions})}
 <div class="v2-section-bar"><h2>Lista de aulas</h2><span>Escolha pelo nível</span></div>
 <div class="filter-row" role="group" aria-label="Filtrar aulas">${['Todos','A1','A2','B1'].map(f=>`<button class="chip ${app.filter===f?'active':''}" data-action="filter-level" data-value="${f}" aria-pressed="${app.filter===f}">${f==='Todos'?'Todas as aulas':f}</button>`).join('')}</div><div class="section-head"><h2 class="section-title">Suas aulas</h2><span class="minor">${filtered.length} lições · ${data.completed.length} concluídas</span></div><div class="lesson-list">${filtered.map(l=>`<button class="lesson-card" data-action="open-lesson" data-id="${l.id}"><span class="lesson-number">${String(lessons.indexOf(l)+1).padStart(2,'0')}</span>${renderLessonListArt(l.id)}<span><h3>${safe(l.title)}</h3><p>${safe(l.subtitle)}</p></span><span class="lesson-meta"><span class="time">${l.level} · 6 min</span><span class="completion-dot ${data.completed.includes(l.id)?'done':''}" aria-label="${data.completed.includes(l.id)?'Concluída':'Pendente'}">${data.completed.includes(l.id)?'✓':'↗'}</span></span></button>`).join('')}</div>`}
function lessonPage(){const l=lessons.find(x=>x.id===app.lesson)||lessons[0],q=l.qs[app.lessonIdx],done=app.lessonIdx>=l.qs.length;return `<button class="back-link" data-route="learn">← Voltar à trilha</button><div class="lesson-top"><span class="pill">${l.level}</span><span class="pill warm">AULA ${String(lessons.indexOf(l)+1).padStart(2,'0')}</span><span class="minor">~ 6 minutos</span></div>${renderLessonMeter(app.lessonIdx,l.qs.length)}<h1 class="heading">${safe(l.title)}<span style="color:#c6d3bb">.</span></h1><p class="lesson-lede">${safe(l.subtitle)}. ${safe(l.why)}</p>${renderLessonWorld(l.id)}${renderLessonFeature(l.id,l.level)}
<section class="theory-card"><span class="overline">01 / ENTENDA A IDEIA</span><h2>Qual é a lógica?</h2><p>${safe(l.rule)}</p><div class="formula">${l.form.map((s,i)=>`${i?'<i>+</i>':''}<span>${safe(s)}</span>`).join('')}</div><div class="example-box"><div class="en">${safe(l.example)} <button class="audio-button" data-action="speak-audio" data-say="${encodeURIComponent(l.example)}" aria-label="Ouvir exemplo em inglês">${svg('audio')}</button></div><div class="pt">${safe(l.translation)}</div></div><p><strong>Guarde isso:</strong> ${safe(l.tip)}</p><div class="error-compare"><small>ERRO COMUM → CORREÇÃO</small><div class="wrong">${safe(l.wrong)}</div><div class="right">${safe(l.right)}</div></div></section>
${done?`<section class="endcard vb-lesson-endcard">${renderLessonResultArt(l.id,app.lessonScore===l.qs.length)}<span class="overline">AULA FINALIZADA</span><h2>${app.lessonScore===l.qs.length?'Muito bem. Você entendeu a estrutura.':'Quase lá. Vale refazer.'}</h2><p>${app.lessonScore===l.qs.length?`Você acertou ${app.lessonScore} de ${l.qs.length} questões. Esta aula foi marcada como concluída.`:`Você acertou ${app.lessonScore} de ${l.qs.length} questões. Para concluir, tente novamente e acerte todas. Os erros também estão na sua revisão.`}</p><div class="hero-actions"><button class="button" data-action="restart-lesson">Refazer aula</button><button class="button outline" data-route="learn">Escolher outra aula ${svg('arrow')}</button></div></section>`:
`<section class="exercise-card"><div class="round-top"><span>02 / COLOQUE EM PRÁTICA</span><span>${app.lessonIdx+1} de ${l.qs.length}</span></div><h2>Você consegue completar?</h2><div class="exercise-progress">${l.qs.map((_,i)=>`<i class="${i<=app.lessonIdx?'complete':''}"></i>`).join('')}</div><p class="quiz-prompt">${safe(q[0])}</p><div class="answers">${q[1].map((opt,i)=>`<button class="answer ${app.lessonAnswer?(opt===q[2]?'correct':opt===app.lessonAnswer.value?'incorrect':''):''}" data-action="lesson-answer" data-value="${safe(opt)}" ${app.lessonAnswer?'disabled':''}><span class="key">${String.fromCharCode(65+i)}</span>${safe(opt)}</button>`).join('')}</div>${app.lessonAnswer?`<div class="feedback ${app.lessonAnswer.ok?'good':''}" role="status"><strong>${app.lessonAnswer.ok?'Correto!':'Ainda não. A forma correta é '+safe(q[2])+'.'}</strong>${safe(q[3])}</div><button class="button" data-action="lesson-next">${app.lessonIdx+1===l.qs.length?'Ver meu resultado':'Próxima pergunta'} ${svg('arrow')}</button>`:'<small class="tool-tip">Escolha uma alternativa para receber explicação imediata.</small>'}</section>`}`}
function labPage(){if(app.labTab==='verbs'){const query=app.verbQuery.trim().toLowerCase();const filtered=verbs.filter(v=>v.join(' ').toLowerCase().includes(query));return `<div class="page-intro"><div class="overline">REFERÊNCIA · SEM DECORAR TABELAS INFINITAS</div><h1 class="heading">O laboratório <em>verbal.</em></h1><p class="lede">Duas ferramentas para descobrir a forma certa: comparação de tempos verbais e um dicionário de verbos frequentes.</p></div><div class="filter-row"><button class="chip" data-action="lab-tab" data-value="tenses">Tempos verbais</button><button class="chip active" data-action="lab-tab" data-value="verbs">Dicionário de verbos</button></div><div class="verb-search"><input class="search-input" id="verb-query" placeholder="Buscar: go, went, falar, escrever..." value="${safe(app.verbQuery)}" aria-label="Buscar verbo" autocomplete="off" /></div><div id="verb-result">${verbResults(filtered)}</div>`}
const t=tenses.find(x=>x.id===app.tense)||tenses[0];return `<div class="page-intro"><div class="overline">GRAMÁTICA EM CONTEXTO</div><h1 class="heading">O laboratório <em>verbal.</em></h1><p class="lede">Entenda como o tempo transforma uma frase. Compare estrutura, intenção e exemplos antes de tentar usar no diálogo.</p></div><div class="filter-row"><button class="chip active" data-action="lab-tab" data-value="tenses">Tempos verbais</button><button class="chip" data-action="lab-tab" data-value="verbs">Dicionário de verbos</button></div><div class="tense-layout"><div class="tense-tabs" role="tablist" aria-label="Tempos verbais">${tenses.map(x=>`<button class="tense-tab ${x.id===app.tense?'active':''}" role="tab" aria-selected="${x.id===app.tense}" data-action="tense-select" data-id="${x.id}"><span>${x.level} · TEMPO VERBAL</span><strong>${x.name}</strong></button>`).join('')}</div><article class="tense-sheet"><span class="overline">CADERNO DE TEMPOS · ${t.level}</span><h2>${t.name}</h2><p>${safe(t.usage)}</p><div class="tense-axis"><div class="overline" style="font-size:9px">LINHA DO TEMPO · VISÃO DIDÁTICA</div><div class="time-track">${[0,1,2].map(i=>`<i class="time-point ${t.point===i?'hot':''}"></i>`).join('')}</div><div class="time-labels"><span>Passado</span><span>Presente</span><span>Futuro</span></div></div><div class="overline" style="font-size:10px">ESTRUTURA</div><div class="formula"><span>${safe(t.formula)}</span></div><div class="example-box"><div class="en">${safe(t.en)} <button class="audio-button" data-action="speak-audio" data-say="${encodeURIComponent(t.en)}" aria-label="Ouvir exemplo">${svg('audio')}</button></div><div class="pt">${safe(t.pt)}</div></div><table class="tense-table"><tbody>${t.examples.map(ex=>`<tr><td>${safe(ex[0])}</td><td>${safe(ex[1])} <button class="audio-button" data-action="speak-audio" data-say="${encodeURIComponent(ex[1])}" aria-label="Ouvir frase">${svg('audio')}</button></td></tr>`).join('')}</tbody></table><div class="overline" style="font-size:10px;margin-bottom:11px">PALAVRAS QUE DÃO PISTAS</div><div class="keyword-line">${t.keywords.map(x=>`<span>${safe(x)}</span>`).join('')}</div><div class="explain-tip"><strong>Atenção:</strong> ${safe(t.tip)}</div><div style="margin-top:23px"><button class="button" data-route="practice">Praticar este conteúdo ${svg('arrow')}</button></div></article></div>`}
function verbResults(filtered){return `<div class="verb-table-scroll"><table class="verb-table"><thead><tr><th>Verbo</th><th>Passado</th><th>Particípio</th><th>Significado</th><th>Áudio</th></tr></thead><tbody>${filtered.map(v=>`<tr><td><strong>${safe(v[0])}</strong></td><td>${safe(v[1])}</td><td>${safe(v[2])}</td><td>${safe(v[3])}</td><td><button data-action="speak-audio" data-say="${encodeURIComponent(v[0])}" aria-label="Ouvir ${safe(v[0])}">${svg('audio')}</button></td></tr>`).join('')}</tbody></table></div>${!filtered.length?'<div class="empty-state">Nenhum verbo encontrado. Tente outra busca.</div>':''}<p class="tool-tip" style="margin-top:17px">O particípio é usado, por exemplo, depois de have / has no Present Perfect. Algumas formas variam entre inglês britânico e americano.</p>`}
function shuffle(xs){const arr=[...xs];for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]]}return arr}
function newRound(reviewOnly=false){const pool=reviewOnly?dueItems().map(([id])=>findQ(id)).filter(Boolean):allQuestions().filter(q=>app.practiceMode==='mixed'||(app.practiceMode==='choice'&&q.type==='choice')||(app.practiceMode==='write'&&q.type==='write'));app.round=shuffle(pool).slice(0,reviewOnly?Math.min(10,pool.length):8);app.roundIdx=0;app.roundCorrect=0;app.roundAnswer=null;app.reviewOnly=reviewOnly}
function practicePage(){if(!app.round.length&&!app.reviewOnly)newRound();const ended=app.roundIdx>=app.round.length;if(app.reviewOnly&&!app.round.length)return `<div class="page-intro"><div class="overline">REVISÃO</div><h1 class="heading">Nada pendente <em>agora.</em></h1><p class="lede">Suas respostas incorretas reaparecem aqui. Faça outras práticas ou volte quando houver revisões disponíveis.</p></div><button class="button" data-action="practice-mode" data-value="mixed">Começar exercícios gerais ${svg('arrow')}</button>`;
const q=app.round[app.roundIdx];return `<div class="page-intro"><div class="overline">PRÁTICA ATIVA ${app.reviewOnly?'· REVISÃO DE ERROS':''}</div><h1 class="heading">Pense primeiro.<br><em>Responda depois.</em></h1><p class="lede">Treine reconhecimento e produção. A correção explica a regra por trás de cada resposta.</p></div>${!app.reviewOnly?`<div class="mode-tabs" role="group" aria-label="Tipo de exercício">${[['mixed','Misturado'],['choice','Escolha a opção'],['write','Escreva a resposta']].map(([v,label])=>`<button class="chip ${app.practiceMode===v?'active':''}" data-action="practice-mode" data-value="${v}" aria-pressed="${app.practiceMode===v}">${label}</button>`).join('')}</div>`:`<button class="back-link" data-route="review">← Voltar às revisões</button>`}
${ended?`<section class="endcard"><span class="overline">RODADA CONCLUÍDA</span><h2>${app.roundCorrect} de ${app.round.length} respostas corretas.</h2><p>${app.roundCorrect===app.round.length?'Você acertou toda a rodada. Continue usando essas estruturas em voz alta.':'Veja as explicações das questões que errou. Elas podem aparecer novamente na revisão.'}</p><div class="hero-actions"><button class="button" data-action="new-round">Nova rodada ${svg('arrow')}</button><button class="button outline" data-route="review">Ver revisões</button></div></section>`:`<section class="practice-panel"><div class="round-top"><span>${q.type==='write'?'PRODUÇÃO ESCRITA':'RECONHECIMENTO DE ESTRUTURA'}</span><span>${app.roundIdx+1} / ${app.round.length}</span></div><div class="exercise-progress" style="margin-top:15px">${app.round.map((_,i)=>`<i class="${i<app.roundIdx+1?'complete':''}"></i>`).join('')}</div><h2 class="quiz-prompt">${safe(q.prompt)}</h2><p class="practice-desc">${q.type==='write'?`Use a dica de estrutura: ${safe(q.hint)}.`:'Selecione a melhor alternativa.'}</p>${q.type==='choice'?`<div class="answers">${q.options.map((opt,i)=>`<button class="answer ${app.roundAnswer?(opt===q.correct?'correct':opt===app.roundAnswer.value?'incorrect':''):''}" data-action="practice-answer" data-value="${safe(opt)}" ${app.roundAnswer?'disabled':''}><span class="key">${String.fromCharCode(65+i)}</span>${safe(opt)}</button>`).join('')}</div>`:`<div class="text-answer"><label for="write-answer">SUA RESPOSTA EM INGLÊS</label><input class="text-input" id="write-answer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Escreva aqui..." value="${safe(app.roundAnswer?.value||'')}" ${app.roundAnswer?'disabled':''}/></div>${!app.roundAnswer?`<button class="button" data-action="practice-submit">Conferir resposta ${svg('arrow')}</button>`:''}`}
${app.roundAnswer?`<div class="feedback ${app.roundAnswer.ok?'good':''}" role="status"><strong>${app.roundAnswer.ok?'Boa! Resposta correta.':'Resposta esperada: '+safe(q.type==='write'?q.answer:q.correct)}</strong>${safe(q.explain)}${q.type==='write'?'<br><small>Correção textual por respostas aceitas, não avaliação semântica livre.</small>':''}</div><div class="practice-footer"><small>${app.roundCorrect} acerto(s) nesta rodada</small><button class="button" data-action="practice-next">${app.roundIdx+1===app.round.length?'Ver resultado':'Próxima questão'} ${svg('arrow')}</button></div>`:`<div class="practice-footer"><small>Dica: tente sem traduzir palavra por palavra.</small><small>⏎ Enter envia respostas escritas</small></div>`}</section>`}`}
function speakPage(){const sc=scenarios.find(x=>x.id===app.scenario)||scenarios[0],finished=app.step>=sc.steps.length;const step=sc.steps[app.step];let messages=[...app.dialog];if(!finished)messages.push({mine:false,text:step.ask,pt:step.pt});const chat=messages.map(m=>`<div class="chat-item ${m.mine?'mine':''}"><span class="chat-avatar vb3-chat-avatar" aria-hidden="true"><img src="/verbarium-v3/assets/speaking/${m.mine?'student_boy':'student_girl'}.png" alt="" decoding="async"></span><div class="bubble">${safe(m.text)}${m.pt?`<small>${safe(m.pt)}</small>`:''}${!m.mine?`<button class="audio-button" data-action="speak-audio" data-say="${encodeURIComponent(m.text)}" aria-label="Ouvir fala">${svg('audio')}</button>`:''}</div></div>`).join('');return `<div class="page-intro"><div class="overline">PRÁTICA DE CONVERSAÇÃO · DIÁLOGOS GUIADOS</div><h1 class="heading">A conversa começa<br>com <em>uma resposta.</em></h1><p class="lede">Escolha uma situação, ouça a pergunta e responda. O treino oferece frases naturais e explica por que cada escolha funciona.</p></div><div class="scenario-grid">${scenarios.map(s=>`<button class="scenario-card ${s.id===app.scenario?'active':''}" data-action="select-scenario" data-id="${s.id}" aria-pressed="${s.id===app.scenario}"><span class="scene-art scene-art-${s.id}" aria-hidden="true"><img src="/icons/3d/${s.id}.png" alt="" width="72" height="72" loading="lazy" decoding="async"></span><span class="scene-index">${s.icon}</span><h3>${safe(s.title)}</h3><p>${safe(s.desc)}</p></button>`).join('')}</div><section class="conversation-window"><div class="conversation-head"><div><span class="overline">SIMULAÇÃO ${sc.icon} / ${sc.steps.length} TROCAS</span><h3>${safe(sc.title)}</h3></div><button class="button outline small" data-action="reset-scenario">Recomeçar</button></div><div class="chat-history" id="chat-history">${chat}</div><div class="conversation-controls">${finished?`<div class="endcard"><div class="overline">CONVERSA CONCLUÍDA</div><h2>Você manteve o diálogo.</h2><p>Agora repita as falas em voz alta sem ler o texto.</p><button class="button" data-action="reset-scenario">Praticar novamente ${svg('arrow')}</button></div>`:`<div class="round-top"><span>SUA VEZ DE RESPONDER</span><span>${app.step+1} / ${sc.steps.length}</span></div><div class="answers">${step.choices.map((opt,i)=>`<button class="answer ${app.dialogAnswer?(i===step.correct?'correct':i===app.dialogAnswer.index?'incorrect':''):''}" data-action="dialog-choice" data-index="${i}" ${app.dialogAnswer?'disabled':''}><span class="key">${String.fromCharCode(65+i)}</span>${safe(opt)}</button>`).join('')}</div>${app.dialogAnswer?`<div class="feedback ${app.dialogAnswer.ok?'good':''}" role="status"><strong>${app.dialogAnswer.ok?'Resposta adequada.':'A resposta mais natural nesta situação é: '+safe(step.choices[step.correct])}</strong>${safe(step.note)}</div><button class="button" data-action="dialog-next">Continuar diálogo ${svg('arrow')}</button>`:`<div class="mic-row"><button class="mic-button" data-action="speak-audio" data-say="${encodeURIComponent(step.speech)}">${svg('audio')} Ouvir uma boa resposta</button><button class="mic-button" data-action="record-speech"><img class="vb-speech-mic-art" data-vb3-listening="${app.micStatus.startsWith('Ouvindo')}" src="/verbarium-v3/assets/speaking/mic_${app.micStatus.startsWith('Ouvindo')?'listening':'idle'}.png" alt="" aria-hidden="true"> Tentar com a voz</button><small>O microfone é opcional.</small></div><div class="mic-status" role="status">${safe(app.micStatus)}</div>`}<div class="coach-tip"><strong>Como o treino funciona:</strong> o exercício verifica uma escolha ou transcrição aproximada; ele não atribui nota de fluência ou sotaque.</div>`}</div></section>`}

function chapterPage(){
 return renderChapterDetail({id:app.chapter,lessons,completed:data.completed,currentId:nextLesson().id,lessonSessions:data.lessonSessions});
}
function profilePage(){
 return renderProfile({nickname:data.nickname,completed:data.completed,correct:data.correct,attempts:data.attempts,streak:currentStreak(),sessions:data.sessions||[],reviews:data.reviews,due:dueItems().length}) + `<div class="vb-assets-shortcut"><button data-route="assets" type="button">Biblioteca visual do Verbarium · 192 assets <span>↗</span></button></div><div class="vb-motion-shortcut"><button type="button" data-route="motions">Biblioteca de motions · 53 animações <span>↗</span></button></div><div class="vb-motion-shortcut"><button type="button" data-route="v3">Biblioteca v3 · 151 sprites e 142 motions <span>↗</span></button></div>`;
}
function progressPage(){
 const completion=pct(data.completed.length,lessons.length),accuracy=data.attempts?pct(data.correct,data.attempts):0,streak=currentStreak(),daily=weekActivity(),due=dueItems().length;
 const rankText=completion===100?'Trilha completa':completion>=50?'Metade do caminho':completion>0?'Primeiros passos':'Sua jornada começa aqui';
 return `<div class="page-intro"><div class="overline">SEU CRESCIMENTO, NO SEU RITMO</div><h1 class="heading">Cada passo <em>conta!</em> 🏆</h1><p class="lede">Este é seu espaço de conquistas. Acompanhe o que estudou, o que já sabe e onde pode melhorar.</p></div>
 <div class="v2-profile-links v2-progress-shortcuts"><button type="button" data-route="profile">Ver minhas conquistas e perfil <span>↗</span></button></div><div class="vb-assets-shortcut"><button type="button" data-route="assets">Explorar biblioteca visual · 192 assets <span>↗</span></button></div><div class="vb-motion-shortcut"><button type="button" data-route="motions">Explorar os 53 motions <span>↗</span></button></div><div class="vb-motion-shortcut"><button type="button" data-route="v3">Explorar os 151 sprites e 142 motions do v3 <span>↗</span></button></div>
 ${renderProgressOverview({completion,completed:data.completed.length,total:lessons.length,accuracy,attempts:data.attempts,streak,days:daily})}
  ${renderJourneyFlow()}
 <section class="podium-panel"><img class="vb-podium-trophy" src="/verbarium-v3/assets/trophy/${completion===100?'complete':'idle'}.png" loading="lazy" alt="" aria-hidden="true"><div class="podium-sparks" aria-hidden="true">✦ · ✧ ✳</div><div class="podium-head"><span>MINHAS CONQUISTAS</span><h2>${rankText}</h2><p>Sem comparação com outras pessoas. Cada conquista vem da sua prática.</p></div><div class="achievement-pill">✦ ${completion}% da trilha concluída</div>
 <div class="podium-stage"><div class="podium-column second"><div class="podium-medal">${art("chart")}</div><strong>Acertos</strong><span>${data.attempts?accuracy+'%':'—'}</span><div class="podium-block">2</div></div><div class="podium-column first"><div class="podium-medal">${art("book")}</div><strong>Aulas</strong><span>${data.completed.length}</span><div class="podium-block">1</div></div><div class="podium-column third"><div class="podium-medal">${art("flame")}</div><strong>Sequência</strong><span>${streak} dia(s)</span><div class="podium-block">3</div></div></div></section>
 <div class="section-head"><h2 class="section-title">Sua semana ✨</h2><span class="minor">Últimos 7 dias</span></div><section class="activity-panel"><div class="week-days wide">${daily.map(w=>`<span class="weekday ${w.active?'did':''}" title="${w.date}"><strong>${w.label}</strong><i>${w.active?'✓':'·'}</i></span>`).join('')}</div><div class="activity-caption"><span>• Pratique em dias diferentes para construir uma rotina.</span><strong>${daily.filter(x=>x.active).length}/7 dias ativos</strong></div></section>
 <div class="goals-row"><div class="goal-tile"><span class="goal-art">${art("chart")}</span><div><h3>Revisão inteligente</h3><p>${due?`${due} questão(ões) para rever agora.`:'Nenhuma revisão pendente por enquanto.'}</p></div><button class="button outline small" data-route="review">Revisar ${svg('arrow')}</button></div><div class="goal-tile"><span class="goal-art">${art("book")}</span><div><h3>Próxima conquista</h3><p>${completion===100?'Continue consolidando o que aprendeu.':`Faltam ${lessons.length-data.completed.length} aulas para concluir a trilha.`}</p></div><button class="button outline small" data-route="learn">Estudar ${svg('arrow')}</button></div></div><p class="tool-tip">Os indicadores usam somente as atividades realizadas neste navegador. Não representam nota CEFR nem competição com outros alunos.</p>`
}
function reviewPage(){const due=dueItems(),total=reviewItems();return `<div class="page-intro"><div class="overline">MEMÓRIA E REPETIÇÃO</div><h1 class="heading">Errar também<br>é <em>progresso.</em></h1><p class="lede">As questões que você erra viram oportunidades de revisão. Ao acertar depois, elas retornam em intervalos maiores, de 1, 3, 7 e 14 dias.</p></div><div class="stats-strip"><div class="stat"><span class="stat-label">Para revisar agora</span><strong class="stat-value">${due.length}</strong><span class="stat-sub">itens disponíveis</span></div><div class="stat"><span class="stat-label">No seu caderno</span><strong class="stat-value">${total.length}</strong><span class="stat-sub">itens já errados</span></div><div class="stat"><span class="stat-label">Seu histórico</span><strong class="stat-value">${data.attempts}</strong><span class="stat-sub">respostas totais</span></div></div>${!total.length?`<section class="review-empty"><span class="overline">SEU CADERNO ESTÁ LIMPO</span><h2>Nenhum erro registrado ainda.</h2><p>Comece um exercício. Se houver uma resposta incorreta, ela ficará aqui para você praticar novamente.</p><button class="button" data-route="practice">Ir para a prática ${svg('arrow')}</button></section>`:`<div class="section-head"><h2 class="section-title">Seu caderno de erros</h2><span class="minor">${due.length} prontas para hoje</span></div>${due.length?`<button class="button" data-action="review-start" style="margin-bottom:20px">Revisar ${Math.min(10,due.length)} questão(ões) ${svg('arrow')}</button>`:'<p class="lede">Você já revisou o que estava disponível. Os próximos itens aparecem na data indicada.</p>'}${total.map(([id,rv])=>{const q=findQ(id),d=rv.due<=Date.now();return `<div class="review-row"><span class="level-dot ${d?'':'later'}"></span><div style="flex:1;min-width:0"><strong>${safe(q.prompt)}</strong><p>${d?'Disponível para revisar agora':'Retorna em '+new Date(rv.due).toLocaleDateString('pt-BR')} · etapa ${rv.level||0}</p></div><span class="pill">${d?'AGORA':'AGENDADA'}</span></div>`}).join('')}`}<div class="divider-line"></div><button class="text-button" data-action="reset-progress">Limpar o progresso salvo neste navegador</button><p class="tool-tip">Seus dados permanecem no localStorage deste navegador. Não há conta, sincronização nem avaliação oficial de proficiência.</p>`}
function openLesson(id){
 const l=lessons.find(x=>x.id===id)||lessons[0];
 const saved=data.lessonSessions?.[l.id];
 const resume=!data.completed.includes(l.id)&&saved&&Number.isInteger(saved.index)&&saved.index>0&&saved.index<l.qs.length;
 app.lesson=l.id;
 app.lessonIdx=resume?saved.index:0;
 app.lessonAnswer=null;
 app.lessonScore=resume?Math.max(0,Math.min(saved.index,Number(saved.score)||0)):0;
 goto('lesson');
}
function normalize(s){return String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’‘]/g,"'").replace(/[^a-z0-9\s']/g,'').replace(/\s+/g,' ').trim()}
function submitPractice(value){if(app.roundAnswer||app.roundIdx>=app.round.length)return;const q=app.round[app.roundIdx],ok=q.type==='choice'?value===q.correct:q.accepted.some(x=>normalize(x)===normalize(value));if(!String(value??'').trim()){announce('Escreva uma resposta antes de conferir.');document.querySelector('#write-answer')?.focus();return}app.roundAnswer={value,ok};if(ok)app.roundCorrect++;recordAttempt(ok,q.id);paint();announce(ok?'Resposta correta.':'Resposta incorreta. Veja a explicação.')}
function say(text){if(!('speechSynthesis' in window)){announce('Seu navegador não oferece áudio de síntese.');return}window.speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(text);utter.lang='en-US';utter.rate=.86;utter.pitch=1;window.speechSynthesis.speak(utter)}
function trySpeech(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;const sc=scenarios.find(s=>s.id===app.scenario),step=sc.steps[app.step];if(!SpeechRecognition){app.micStatus='Reconhecimento de voz indisponível neste navegador. Use os botões e o áudio.';paint();return}if(!step||app.dialogAnswer)return;const recognition=new SpeechRecognition();recognition.lang='en-US';recognition.interimResults=false;recognition.maxAlternatives=1;app.micStatus='Ouvindo... fale a frase em inglês.';paint();recognition.onresult=e=>{const heard=e.results[0][0].transcript;const expected=step.speech;const a=normalize(heard).split(' '),b=normalize(expected).split(' ');const matches=b.filter(x=>a.includes(x)).length;const approximate=matches/Math.max(a.length,b.length);app.micStatus=`Transcrição: “${heard}”. ${approximate>=.7?'Boa correspondência com a frase sugerida.':'Tente repetir a frase sugerida.'} (Comparação aproximada, não nota de pronúncia.)`;paint();};recognition.onerror=()=>{app.micStatus='Não foi possível usar o microfone. Verifique a permissão ou continue pelos botões.';paint()};try{recognition.start()}catch{app.micStatus='Não foi possível iniciar o microfone. Tente novamente.';paint()}}
function handleAction(button){const a=button.dataset.action,id=button.dataset.id,value=button.dataset.value;
if(a==='open-lesson')return openLesson(id);
if(a==='open-chapter'){app.chapter=chapters.some(c=>c.id===id)?id:'first';return goto('chapter')}
if(a==='filter-level'){app.filter=value;return paint()}
if(a==='lesson-answer'){if(app.lessonAnswer)return;const l=lessons.find(x=>x.id===app.lesson),q=l.qs[app.lessonIdx],ok=value===q[2];app.lessonAnswer={value,ok};if(ok)app.lessonScore++;recordAttempt(ok,`${l.id}-${app.lessonIdx}`);paint();return}
if(a==='lesson-next'){
 const l=lessons.find(x=>x.id===app.lesson);
 app.lessonIdx++;app.lessonAnswer=null;
 data.lessonSessions??={};
 let awarded=false;
 if(app.lessonIdx<l.qs.length){
  data.lessonSessions[l.id]={index:app.lessonIdx,score:app.lessonScore};
 }else{
  delete data.lessonSessions[l.id];
  if(app.lessonScore===l.qs.length&&!data.completed.includes(l.id)){
   data.completed.push(l.id);data.completedAt[l.id]=day();awarded=true;
   const following=lessons.find(x=>!data.completed.includes(x.id));
   queuePhaseReveal(l.id,following?.id||'');
  }
 }
 save();paint();
 if(awarded){
  showVerbariumToast({title:'Aula concluída!',description:'Uma nova conquista na sua jornada de inglês.'});
  celebrateV3({kind:'lesson',lessonId:l.id});
 }
 return;
}
if(a==='restart-lesson'){
 app.lessonIdx=0;app.lessonAnswer=null;app.lessonScore=0;
 if(data.lessonSessions)delete data.lessonSessions[app.lesson];
 save();return paint();
}
if(a==='lab-tab'){app.labTab=value;return paint()}
if(a==='tense-select'){app.tense=id;return paint()}
if(a==='practice-mode'){app.practiceMode=value;newRound();return goto('practice')}
if(a==='practice-answer')return submitPractice(value);
if(a==='practice-submit')return submitPractice(document.querySelector('#write-answer')?.value||'');
if(a==='practice-next'){app.roundIdx++;app.roundAnswer=null;return paint()}
if(a==='new-round'){if(app.reviewOnly&&dueItems().length===0){app.reviewOnly=false;newRound(false)}else newRound(app.reviewOnly);return paint()}
if(a==='review-start'){newRound(true);return goto('practice')}
if(a==='select-scenario'){app.scenario=id;app.step=0;app.dialog=[];app.dialogAnswer=null;app.micStatus='';return paint()}
if(a==='reset-scenario'){app.step=0;app.dialog=[];app.dialogAnswer=null;app.micStatus='';return paint()}
if(a==='dialog-choice'){if(app.dialogAnswer)return;const sc=scenarios.find(x=>x.id===app.scenario),step=sc.steps[app.step],ix=Number(button.dataset.index),ok=ix===step.correct;app.dialogAnswer={index:ix,ok};return paint()}
if(a==='dialog-next'){const sc=scenarios.find(x=>x.id===app.scenario),step=sc.steps[app.step];app.dialog.push({mine:false,text:step.ask,pt:step.pt},{mine:true,text:step.choices[app.dialogAnswer.index]});app.step++;if(app.step===sc.steps.length){data.sessions.push({date:day(),scenario:sc.id});if(data.sessions.length>500)data.sessions=data.sessions.slice(-500);save()}app.dialogAnswer=null;app.micStatus='';paint();if(app.step===sc.steps.length)celebrateV3({kind:'dialogue'});return}
if(a==='speak-audio')return say(decodeURIComponent(button.dataset.say||''));
if(a==='record-speech')return trySpeech();
if(a==='reset-progress'){if(window.confirm('Deseja apagar aulas concluídas, respostas e revisões salvas neste navegador?')){Object.assign(data,defaultData());save();newRound();paint()}return}
}

document.addEventListener('submit',event=>{if(event.target.id!=='v2-profile-name-form')return;event.preventDefault();const input=event.target.querySelector('[name="nickname"]');data.nickname=(input?.value||'').trim().slice(0,24)||'Explorador';save();paint();announce('Nome de exibição salvo neste navegador.');});
document.addEventListener('click',e=>{const routeButton=e.target.closest('button[data-route]');if(routeButton){const route=routeButton.dataset.route;if(route==='practice'&&app.route!=='practice'){app.reviewOnly=false;newRound()}return goto(route)}const actionButton=e.target.closest('button[data-action]');if(actionButton)handleAction(actionButton)});
document.addEventListener('input',e=>{if(e.target.id==='verb-query'){app.verbQuery=e.target.value;document.querySelector('#verb-result').innerHTML=verbResults(verbs.filter(v=>v.join(' ').toLowerCase().includes(app.verbQuery.trim().toLowerCase())))}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.activeElement?.id==='write-answer'&&!app.roundAnswer){e.preventDefault();submitPractice(document.activeElement.value)} });
paint();
